using Seamless.Database.Gateway.Hosting;
using Seamless.Database.Query;
using Seamless.Database.Rdbms;

namespace Seamless.Database.Gateway.Sql;

internal static class GatewayConstraintDefinitions{
    internal static void Validate(GatewaySchemaCatalog schema){
        var tables=schema.Definition.Schemas.SelectMany(owner=>owner.Tables.Select(table=>(Schema:owner.Name,Table:table))).ToArray();
        foreach(var (_,table) in tables){if(table.Columns.Count(static column=>column.Type.SqlTypeName is "rowversion" or "timestamp")>1){throw new SqlQueryException("A table can have only one timestamp column.",2738);}if(table.Columns.Any(static column=>column.Type.SqlTypeName is "rowversion" or "timestamp"&&column.DefaultDefinition is not null)){throw new SqlQueryException("A timestamp column cannot have a DEFAULT.",1755);}}
        foreach(var owner in schema.Definition.Schemas){var names=new HashSet<string>(owner.Tables.Select(static table=>table.Name).Concat(owner.Views.Select(static view=>view.Name)).Concat(owner.Routines.Select(static routine=>routine.Name)),StringComparer.OrdinalIgnoreCase);foreach(var table in owner.Tables){var constraints=new[]{table.PrimaryKey?.Name}.Concat(table.UniqueKeys.Select(static key=>key.Name)).Concat(table.ForeignKeys.Select(static key=>key.Name)).Concat(table.CheckConstraints.Select(static key=>key.Name)).Concat(table.Columns.Select(static column=>column.DefaultConstraintName));foreach(var name in constraints.Where(static name=>name is not null)){if(!names.Add(name!)){throw new SqlQueryException("An object or constraint with this name already exists in the schema.",2714);}}}}
        foreach(var (_,table) in tables){foreach(var key in table.ForeignKeys){
            var parent=tables.SingleOrDefault(item=>Same(item.Schema,key.ReferencedSchema)&&Same(item.Table.Name,key.ReferencedTable)).Table??throw new SqlQueryException("Referenced table does not exist.",1767);var parentKeys=parent.UniqueKeys.Select(static key=>key.Columns).ToList();if(parent.PrimaryKey is{} primary){parentKeys.Add(primary.Columns);}if(!parentKeys.Any(columns=>columns.Count==key.Columns.Count&&columns.Select(static column=>column.Name).SequenceEqual(key.Columns.Select(static pair=>pair.ReferencedColumn),StringComparer.OrdinalIgnoreCase))){throw new SqlQueryException("Referenced columns are not a primary or unique key.",1776);}
            foreach(var pair in key.Columns){var column=table.Columns.SingleOrDefault(column=>Same(column.Name,pair.Column))??throw new SqlQueryException("Foreign key column does not exist.",1769);var referenced=parent.Columns.SingleOrDefault(column=>Same(column.Name,pair.ReferencedColumn))??throw new SqlQueryException("Referenced column does not exist.",1770);if(column.Type.Kind!=referenced.Type.Kind||!Same(column.Type.SqlTypeName??"",referenced.Type.SqlTypeName??"")||column.Type.Scale!=referenced.Type.Scale||column.Type.Precision!=referenced.Type.Precision||!Same(column.Type.Collation??"",referenced.Type.Collation??"")){throw new SqlQueryException("The foreign key column type, precision, scale, or collation differs.",1778);}if((key.DeleteAction=="SET_NULL"||key.UpdateAction=="SET_NULL")&&!column.Type.IsNullable){throw new SqlQueryException("SET NULL requires nullable foreign key columns.",1761);}if((key.DeleteAction=="SET_DEFAULT"||key.UpdateAction=="SET_DEFAULT")&&!column.Type.IsNullable&&column.DefaultDefinition is null){throw new SqlQueryException("SET DEFAULT requires a default or nullable column.",1762);}}
        }}
        foreach(var update in new[]{false,true}){var edges=tables.SelectMany(parent=>tables.SelectMany(child=>child.Table.ForeignKeys.Where(key=>Same(key.ReferencedSchema,parent.Schema)&&Same(key.ReferencedTable,parent.Table.Name)&&(update?key.UpdateAction:key.DeleteAction)!="NO_ACTION").Select(_=>(Parent:Name(parent.Schema,parent.Table.Name),Child:Name(child.Schema,child.Table.Name))))).ToArray();foreach(var start in tables){var visited=new HashSet<string>(StringComparer.OrdinalIgnoreCase){Name(start.Schema,start.Table.Name)};void Walk(string parent){foreach(var edge in edges.Where(edge=>Same(edge.Parent,parent))){if(!visited.Add(edge.Child)){throw new SqlQueryException("Cascading foreign keys introduce a cycle or multiple cascade paths.",1785);}Walk(edge.Child);}}Walk(Name(start.Schema,start.Table.Name));}}
    }
    private static bool Same(string first,string second)=>first.Equals(second,StringComparison.OrdinalIgnoreCase);
    private static string Name(string schema,string table)=>schema+"\0"+table;
}
